&lt;link rel=&#34;stylesheet&#34; href=&#34;https://fastly.jsdelivr.net/npm/markmap-toolbar@0.18.10/dist/style.css&#34;&gt;&lt;script src=&#34;https://fastly.jsdelivr.net/npm/d3@7&#34;&gt;&lt;/script&gt;&lt;script src=&#34;https://fastly.jsdelivr.net/npm/markmap-view@0.18.10&#34;&gt;&lt;/script&gt;&lt;script src=&#34;https://fastly.jsdelivr.net/npm/markmap-toolbar@0.18.10&#34;&gt;&lt;/script&gt;
&lt;link rel=&#34;stylesheet&#34; href=&#34;/css/markmap.css&#34;&gt;

&lt;script src=&#34;/js/markmap.js&#34;&gt;&lt;/script&gt;

 &lt;blockquote&gt;
&lt;p&gt;&lt;a href=&#34;https://github.com/umami-software/umami&#34;&gt;Umami&lt;/a&gt; 是一个开源网页访问统计服务，类似Google Analytics。专注于简单，快速，隐私安全。相对于把数据交给大公司，收到各种各样的限制，各种付费解锁功能，自建访问统计，自己掌握访问统计数据更好！还可以统计网页的PV, UV，功能定制化更高！&lt;/p&gt;
&lt;/blockquote&gt;
&lt;span id=&#34;more&#34;&gt;&lt;/span&gt;
&lt;p&gt;&lt;img src=&#34;https://cimg1.17lai.site/data/2025/05/02/20250502182221.webp&#34; alt=&#34;Umami&#34;&gt;&lt;/p&gt;
&lt;h2 id=&#34;Umami-统计&#34;&gt;Umami 统计&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;本文同时包含 Umami v2（旧版）和 v3（最新版）的说明。v2 内容已标注，如果你是全新安装请直接看 v3 部分。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;hr&gt;
&lt;h3 id=&#34;安装（v2-版本）&#34;&gt;安装（v2 版本）&lt;/h3&gt;
&lt;p&gt;创建下面这些文件&lt;/p&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-ini&#34; data-language=&#34;ini&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-ini&#34;&gt;# .env
UMAMI_DB_USER&amp;#x3D;umami
UMAMI_DB_PASSWORD&amp;#x3D;password
UMAMI_DB_NAME&amp;#x3D;umami
UMAMI_APP_SECRET&amp;#x3D;vwVXxxxxxLLJWSC&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-yaml&#34; data-language=&#34;yaml&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-yaml&#34;&gt;# docker-compose.yaml
services:
  umami:
    build:
      context: https:&amp;#x2F;&amp;#x2F;github.com&amp;#x2F;umami-software&amp;#x2F;umami.git#v2.15.1
      args:
        BASE_PATH: &amp;#x2F;umami
        DATABASE_TYPE: postgresql
    environment:
      PORT: &amp;quot;4000&amp;quot;
      DATABASE_URL: postgres:&amp;#x2F;&amp;#x2F;$&amp;#123;UMAMI_DB_USER&amp;#125;:$&amp;#123;UMAMI_DB_PASSWORD&amp;#125;@umami-db:5432&amp;#x2F;$&amp;#123;UMAMI_DB_NAME&amp;#125;
      DATABASE_TYPE: postgresql
      APP_SECRET: $&amp;#123;UMAMI_APP_SECRET&amp;#125;
      DISABLE_TELEMETRY: 1
    healthcheck:
      test: [&amp;quot;CMD-SHELL&amp;quot;, &amp;quot;curl http:&amp;#x2F;&amp;#x2F;localhost:4000&amp;#x2F;api&amp;#x2F;heartbeat&amp;quot;]
      interval: 60s
      timeout: 15s
      retries: 5
    depends_on:
      umami-db:
        condition: service_healthy
    deploy:
      resources:
        limits:
          memory: 2G
          cpus: &amp;quot;1&amp;quot;

  umami-db:
    image: postgres:15-alpine
    environment:
      - POSTGRES_PASSWORD&amp;#x3D;$&amp;#123;UMAMI_DB_PASSWORD&amp;#125;
      - POSTGRES_USER&amp;#x3D;$&amp;#123;UMAMI_DB_USER&amp;#125;
      - POSTGRES_DB&amp;#x3D;$&amp;#123;UMAMI_DB_NAME&amp;#125;
    healthcheck:
      test: [&amp;quot;CMD-SHELL&amp;quot;, &amp;quot;pg_isready -U $$&amp;#123;POSTGRES_USER&amp;#125; -d $$&amp;#123;POSTGRES_DB&amp;#125;&amp;quot;]
      interval: 60s
      timeout: 15s
      retries: 5
    volumes:
      - umami_pg_data:&amp;#x2F;var&amp;#x2F;lib&amp;#x2F;postgresql&amp;#x2F;data

volumes:
  umami_pg_data:&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;# docker build and install
$ docker compose up --wait --wait-timeout 360

# docker umami logs 查看
$ docker compose logs umami&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;hr&gt;
&lt;h2 id=&#34;迁移到-Umami-v3&#34;&gt;迁移到 Umami v3&lt;/h2&gt;
&lt;p&gt;Umami 从 v3 开始&lt;strong&gt;移除了 MySQL 支持&lt;/strong&gt;，仅保留 PostgreSQL。同时引入了更安全的 &lt;strong&gt;Share Token&lt;/strong&gt; 机制，用于前端公开统计展示，无需再暴露任何用户凭据。&lt;/p&gt;
&lt;h3 id=&#34;v2-→-v3-主要变化&#34;&gt;v2 → v3 主要变化&lt;/h3&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;项目&lt;/th&gt;
&lt;th&gt;v2&lt;/th&gt;
&lt;th&gt;v3&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;数据库&lt;/td&gt;
&lt;td&gt;MySQL / PostgreSQL&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;仅 PostgreSQL&lt;/strong&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;前端认证&lt;/td&gt;
&lt;td&gt;&lt;code&gt;Authorization: Bearer&lt;/code&gt;（用户 JWT）&lt;/td&gt;
&lt;td&gt;&lt;code&gt;X-Umami-Share-Token&lt;/code&gt;（网站级只读 token）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;响应格式&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123;&amp;quot;pageviews&amp;quot;:&amp;#123;&amp;quot;value&amp;quot;:N&amp;#125;&amp;#125;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123;&amp;quot;pageviews&amp;quot;: N&amp;#125;&lt;/code&gt;（直接数字）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;页面过滤参数&lt;/td&gt;
&lt;td&gt;&lt;code&gt;url&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;path&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;时间戳单位&lt;/td&gt;
&lt;td&gt;毫秒&lt;/td&gt;
&lt;td&gt;毫秒（不变）&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;h3 id=&#34;安装-v3（全新安装）&#34;&gt;安装 v3（全新安装）&lt;/h3&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-yaml&#34; data-language=&#34;yaml&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-yaml&#34;&gt;# docker-compose.yaml (v3)
services:
  umami:
    image: ghcr.io&amp;#x2F;umami-software&amp;#x2F;umami:latest
    ports:
      - &amp;quot;3000:3000&amp;quot;
    environment:
      DATABASE_URL: postgresql:&amp;#x2F;&amp;#x2F;$&amp;#123;UMAMI_DB_USER&amp;#125;:$&amp;#123;UMAMI_DB_PASSWORD&amp;#125;@umami-db:5432&amp;#x2F;$&amp;#123;UMAMI_DB_NAME&amp;#125;
      DATABASE_TYPE: postgresql
      APP_SECRET: $&amp;#123;UMAMI_APP_SECRET&amp;#125;
    depends_on:
      umami-db:
        condition: service_healthy

  umami-db:
    image: postgres:16-alpine
    environment:
      POSTGRES_PASSWORD: $&amp;#123;UMAMI_DB_PASSWORD&amp;#125;
      POSTGRES_USER: $&amp;#123;UMAMI_DB_USER&amp;#125;
      POSTGRES_DB: $&amp;#123;UMAMI_DB_NAME&amp;#125;
    healthcheck:
      test: [&amp;quot;CMD-SHELL&amp;quot;, &amp;quot;pg_isready -U $$&amp;#123;POSTGRES_USER&amp;#125;&amp;quot;]
    volumes:
      - umami_pg_data:&amp;#x2F;var&amp;#x2F;lib&amp;#x2F;postgresql&amp;#x2F;data

volumes:
  umami_pg_data:&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;h3 id=&#34;MySQL-→-PostgreSQL-迁移（v2-升级-v3）&#34;&gt;MySQL → PostgreSQL 迁移（v2 升级 v3）&lt;/h3&gt;
&lt;p&gt;如果已有 v2 MySQL 数据需要迁移，官方推荐步骤如下：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;先安装 v2 PostgreSQL 版本&lt;/strong&gt;，让 Prisma 创建好正确的表结构&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;清空 &lt;code&gt;_prisma_migrations&lt;/code&gt; 和 &lt;code&gt;user&lt;/code&gt; 表&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;用 pgloader 将 MySQL 数据导入 PostgreSQL&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;升级到 v3 镜像&lt;/strong&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;具体迁移步骤可参考 &lt;a href=&#34;https://umami.is/docs/guides/migrate-mysql-postgresql&#34;&gt;官方迁移文档&lt;/a&gt;。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;Umami-UV-PV-统计显示（v3-方案）&#34;&gt;Umami UV / PV 统计显示（v3 方案）&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;Umami 统计了 UV PV 等各种访问数据。v3 提供了 &lt;strong&gt;Share Token&lt;/strong&gt; 机制，可以为单个网站生成一个只读的 JWT token，暴露在前端也没有安全风险。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;方案对比&#34;&gt;方案对比&lt;/h3&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;方案&lt;/th&gt;
&lt;th&gt;安全性&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;s&gt;v2: View only 用户 Bearer token&lt;/s&gt;&lt;/td&gt;
&lt;td&gt;❌ 泄露可查看&lt;strong&gt;所有&lt;/strong&gt;网站&lt;/td&gt;
&lt;td&gt;v3 中已失效（权限检查变更）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;v3: Share Token&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;✅ 泄露仅限&lt;strong&gt;单个&lt;/strong&gt;网站 stats&lt;/td&gt;
&lt;td&gt;本文推荐方案&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;hr&gt;
&lt;h2 id=&#34;Umami-UV-PV-统计显示（v2-方案）&#34;&gt;Umami UV / PV 统计显示（v2 方案）&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;以下为 v2 版本的配置方式，v3 请参考上方。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;新建-View-only-权限的用户（v2）&#34;&gt;新建 &lt;code&gt;View only&lt;/code&gt; 权限的用户（v2）&lt;/h3&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-none&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;Settings&amp;#96; -&amp;gt; &amp;#96;Users&amp;#96; -&amp;gt; &amp;#96;Create user&amp;#96; -&amp;gt; 填写账号密码，&amp;#96;Role&amp;#96; 选择 &amp;#96;View only&amp;#96; -&amp;gt; &amp;#96;Save&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;p&gt;&lt;img src=&#34;https://cimg1.17lai.site/data/2024/03/28/20240328054222.webp&#34; alt=&#34;新建用户&#34;&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;Q: 为什么不直接调用 Umami 的 API 获取数据，而是要额外创建一个账户？&lt;/p&gt;
&lt;p&gt;A: 博客是 &lt;strong&gt;静态开源无服务器&lt;/strong&gt; 的，所有代码都展示在前端，包括 API 调用。而 Umami 的 &lt;code&gt;admin&lt;/code&gt; API 权限太大了，如果使用 &lt;code&gt;admin&lt;/code&gt; 权限的 API Token，那么这个 token 可以获取、修改、删除所有网站的数据，会有严重的安全隐患。&lt;/p&gt;
&lt;p&gt;所以我们需要创建一个 &lt;code&gt;View only&lt;/code&gt; 权限的用户，使用这个 &lt;code&gt;低权限的用户&lt;/code&gt;的 API Token 来访问我们的浏览量等数据。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;新建-Team-并添加用户和网站&#34;&gt;新建 &lt;code&gt;Team&lt;/code&gt; 并添加用户和网站&lt;/h3&gt;
&lt;p&gt;&lt;code&gt;Settings&lt;/code&gt; -&amp;gt; &lt;code&gt;Teams&lt;/code&gt; -&amp;gt; &lt;code&gt;Create team&lt;/code&gt; -&amp;gt; 填写名称 -&amp;gt; &lt;code&gt;Save&lt;/code&gt; -&amp;gt; 找到刚刚创建的 &lt;code&gt;Team&lt;/code&gt; -&amp;gt; &lt;code&gt;Edit&lt;/code&gt; -&amp;gt; 复制 &lt;code&gt;Access code&lt;/code&gt;，点击 &lt;code&gt;Websites&lt;/code&gt; 中点击 &lt;code&gt;Add website&lt;/code&gt; 选中你想共享的网站&lt;/p&gt;
&lt;p&gt;换一个浏览器登录 Umami（使用&lt;code&gt;View only&lt;/code&gt; 权限的用户） -&amp;gt; &lt;code&gt;Settings&lt;/code&gt; -&amp;gt; &lt;code&gt;Teams&lt;/code&gt; -&amp;gt; &lt;code&gt;Join team&lt;/code&gt; -&amp;gt; 输入 &lt;code&gt;Access code&lt;/code&gt; -&amp;gt; &lt;code&gt;Join&lt;/code&gt; -&amp;gt; 如果没有出错的话，点击 &lt;code&gt;Dashboard&lt;/code&gt; 就可以看到你刚刚添加的网站了&lt;/p&gt;
&lt;h3 id=&#34;获取-View-only-用户的-API-Token&#34;&gt;获取 &lt;code&gt;View only&lt;/code&gt; 用户的 API Token&lt;/h3&gt;
&lt;p&gt;根据 Umami 的文档，我们可以通过以下方式获取 API Token：&lt;/p&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-awk&#34; data-language=&#34;awk&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-awk&#34;&gt;POST &amp;#x2F;api&amp;#x2F;auth&amp;#x2F;login&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;p&gt;例如 你的网站地址为 &lt;code&gt;example.com&lt;/code&gt;，那么你需要使用 &lt;code&gt;View only&lt;/code&gt; 的账户密码向 &lt;code&gt;https://example.com/api/auth/login&lt;/code&gt; 发送一个 POST 请求，请求体为：&lt;/p&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-json&#34; data-language=&#34;json&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-json&#34;&gt;&amp;#123;
  &amp;quot;username&amp;quot;: &amp;quot;your-username&amp;quot;,
  &amp;quot;password&amp;quot;: &amp;quot;your-password&amp;quot;
&amp;#125;&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;p&gt;如果成功，你应该会得到以下的结果：&lt;/p&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-json&#34; data-language=&#34;json&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-json&#34;&gt;&amp;#123;
  &amp;quot;token&amp;quot;: &amp;quot;eyTMjU2IiwiY...4Q0JDLUhWxnIjoiUE_A&amp;quot;,
  &amp;quot;user&amp;quot;: &amp;#123;
    &amp;quot;id&amp;quot;: &amp;quot;cd33a605-d785-42a1-9365-d6cad3b7befd&amp;quot;,
    &amp;quot;username&amp;quot;: &amp;quot;your-username&amp;quot;,
    &amp;quot;createdAt&amp;quot;: &amp;quot;2020-04-20 01:00:00&amp;quot;
  &amp;#125;
&amp;#125;&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;p&gt;保存 token 值，并在所有请求中发送带 &lt;code&gt;Bearer &amp;lt;token&amp;gt;&lt;/code&gt; 值的 &lt;code&gt;Authorization&lt;/code&gt; 标头。请求标头应该如下所示：&lt;/p&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-nginx&#34; data-language=&#34;nginx&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-nginx&#34;&gt;Authorization: Bearer eyTMjU2IiwiY...4Q0JDLUhWxnIjoiUE_A&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;h3 id=&#34;发送请求获取数据&#34;&gt;发送请求获取数据&lt;/h3&gt;
&lt;p&gt;这里要用到类似于 &lt;code&gt;postman&lt;/code&gt; 的 API 测试工具，可以使用的是开源的 &lt;a href=&#34;https://github.com/hoppscotch/hoppscotch&#34;&gt;hoppscotch&lt;/a&gt;，你也可以使用 &lt;code&gt;curl&lt;/code&gt; 或者其他工具。&lt;/p&gt;
&lt;p&gt;先分析一下官方文档的 API 接口：&lt;br&gt;
&lt;code&gt;GET /api/websites/&amp;#123;websiteId&amp;#125;/stats&lt;/code&gt;&lt;br&gt;
&lt;img src=&#34;https://cimg1.17lai.site/data/2024/03/28/20240328054222-1.webp&#34; alt=&#34;API&#34;&gt;&lt;/p&gt;
&lt;p&gt;有两个必填的 查询参数：&lt;code&gt;startAt&lt;/code&gt; 和 &lt;code&gt;endAt&lt;/code&gt;，都是 Unix 毫秒时间戳，表示开始时间和结束时间&lt;/p&gt;
&lt;p&gt;&lt;code&gt;websiteId&lt;/code&gt; 和 &lt;code&gt;startAt&lt;/code&gt; 需要我们自己获取&lt;/p&gt;
&lt;p&gt;&lt;code&gt;websiteId&lt;/code&gt; 可以在 &lt;code&gt;Dashboard&lt;/code&gt; -&amp;gt; &lt;code&gt;View details&lt;/code&gt; -&amp;gt; 看浏览器栏的地址 &lt;code&gt;https://example.com/websites/&amp;#123;websiteId&amp;#125;&lt;/code&gt; 中找到&lt;/p&gt;
&lt;p&gt;&lt;code&gt;startAt&lt;/code&gt; 可发送 &lt;code&gt;GET&lt;/code&gt; 请求到 &lt;code&gt;https://example.com/api/websites/&amp;#123;websiteId&amp;#125;&lt;/code&gt;，请求头为&lt;/p&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-nginx&#34; data-language=&#34;nginx&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-nginx&#34;&gt;Authorization: Bearer eyTMjU2IiwiY...4Q0JDLUhWxnIjoiUE_A&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;p&gt;在返回结果中找到 &lt;code&gt;createdAt&lt;/code&gt; 字段，这个字段就是 &lt;code&gt;startAt&lt;/code&gt; 的值，也就是你的网站创建时间，数据的开始时间&lt;br&gt;
&lt;img src=&#34;https://cimg1.17lai.site/data/2024/03/28/20240328054222-2.webp&#34; alt=&#34;createdAt&#34;&gt;&lt;/p&gt;
&lt;h3 id=&#34;编写页面&#34;&gt;编写页面&lt;/h3&gt;
&lt;p&gt;&lt;img src=&#34;https://cimg1.17lai.site/data/2024/03/28/20240328054222-3.webp&#34; alt=&#34;页面展示&#34;&gt;&lt;/p&gt;
&lt;p&gt;代码如下，修改你对应的参数即可运行：&lt;/p&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-markup&#34; data-language=&#34;markup&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-markup&#34;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html lang&amp;#x3D;&amp;quot;en&amp;quot;&amp;gt;

&amp;lt;head&amp;gt;
    &amp;lt;meta charset&amp;#x3D;&amp;quot;UTF-8&amp;quot;&amp;gt;
    &amp;lt;meta name&amp;#x3D;&amp;quot;viewport&amp;quot; content&amp;#x3D;&amp;quot;width&amp;#x3D;device-width, initial-scale&amp;#x3D;1.0&amp;quot;&amp;gt;
    &amp;lt;title&amp;gt;Document&amp;lt;&amp;#x2F;title&amp;gt;
&amp;lt;&amp;#x2F;head&amp;gt;

&amp;lt;body&amp;gt;
    &amp;lt;div style&amp;#x3D;&amp;quot;text-align:center;&amp;quot;&amp;gt;
        &amp;lt;h1&amp;gt;Umami 网站统计&amp;lt;&amp;#x2F;h1&amp;gt;
        &amp;lt;span&amp;gt;总访问量 &amp;lt;span id&amp;#x3D;&amp;quot;umami-site-pv&amp;quot;&amp;gt;&amp;lt;&amp;#x2F;span&amp;gt; 次&amp;lt;&amp;#x2F;span&amp;gt;

        &amp;lt;span&amp;gt;总访客数 &amp;lt;span id&amp;#x3D;&amp;quot;umami-site-uv&amp;quot;&amp;gt;&amp;lt;&amp;#x2F;span&amp;gt; 人&amp;lt;&amp;#x2F;span&amp;gt;
    &amp;lt;&amp;#x2F;div&amp;gt;

    &amp;lt;script&amp;gt;
        &amp;#x2F;&amp;#x2F; 从配置文件中获取 umami 的配置
        const website_id &amp;#x3D; &amp;#39;xxx&amp;#39;;

        &amp;#x2F;&amp;#x2F; 拼接请求地址
        const request_url &amp;#x3D; &amp;#39;https:&amp;#x2F;&amp;#x2F;xxx.com&amp;#39; + &amp;#39;&amp;#x2F;api&amp;#x2F;websites&amp;#x2F;&amp;#39; + website_id + &amp;#39;&amp;#x2F;stats&amp;#39;;

        const start_time &amp;#x3D; new Date(&amp;#39;2024-01-01&amp;#39;).getTime();
        const end_time &amp;#x3D; new Date().getTime();

        const token &amp;#x3D; &amp;#39;xxxxxx&amp;#39;;

        &amp;#x2F;&amp;#x2F; 检查配置是否为空
        if (!website_id) &amp;#123;
            throw new Error(&amp;quot;Umami website_id is empty&amp;quot;);
        &amp;#125;
        if (!request_url) &amp;#123;
            throw new Error(&amp;quot;Umami request_url is empty&amp;quot;);
        &amp;#125;
        if (!start_time) &amp;#123;
            throw new Error(&amp;quot;Umami start_time is empty&amp;quot;);
        &amp;#125;
        if (!token) &amp;#123;
            throw new Error(&amp;quot;Umami token is empty&amp;quot;);
        &amp;#125;

        const params &amp;#x3D; new URLSearchParams(&amp;#123;
            startAt: start_time,
            endAt: end_time,
        &amp;#125;);

        const request_header &amp;#x3D; &amp;#123;
            method: &amp;quot;GET&amp;quot;,
            headers: &amp;#123;
                &amp;quot;Content-Type&amp;quot;: &amp;quot;application&amp;#x2F;json&amp;quot;,
                &amp;quot;Authorization&amp;quot;: &amp;quot;Bearer &amp;quot; + token,
            &amp;#125;,
        &amp;#125;;

        async function allStats() &amp;#123;
            try &amp;#123;
                const response &amp;#x3D; await fetch(&amp;#96;$&amp;#123;request_url&amp;#125;?$&amp;#123;params&amp;#125;&amp;#96;, request_header);
                const data &amp;#x3D; await response.json();
                const uniqueVisitors &amp;#x3D; data.pageviews.value; &amp;#x2F;&amp;#x2F; 获取独立访客数
                const pageViews &amp;#x3D; data.pageviews.value; &amp;#x2F;&amp;#x2F; 获取页面浏览量

                let ele1 &amp;#x3D; document.querySelector(&amp;quot;#umami-site-pv&amp;quot;)
                if (ele1) &amp;#123;
                    ele1.textContent &amp;#x3D; pageViews; &amp;#x2F;&amp;#x2F; 设置页面浏览量
                &amp;#125;

                let ele2 &amp;#x3D; document.querySelector(&amp;quot;#umami-site-uv&amp;quot;)
                if (ele2) &amp;#123;
                    ele2.textContent &amp;#x3D; uniqueVisitors;
                &amp;#125;

                console.log(uniqueVisitors, pageViews);
                console.log(data);
            &amp;#125; catch (error) &amp;#123;
                console.error(error);
                return &amp;quot;-1&amp;quot;;
            &amp;#125;
        &amp;#125;
        allStats();
    &amp;lt;&amp;#x2F;script&amp;gt;
&amp;lt;&amp;#x2F;body&amp;gt;

&amp;lt;&amp;#x2F;html&amp;gt;&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;hr&gt;
&lt;h2 id=&#34;Umami-UV-PV-统计显示（v3-Share-Token-方案）&#34;&gt;Umami UV / PV 统计显示（v3 Share Token 方案）&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;v3 推荐的公开统计方案 — 为每个网站生成独立的 Share Token，暴露在前端也安全。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;1-创建-Share&#34;&gt;1. 创建 Share&lt;/h3&gt;
&lt;p&gt;登录 Umami 后，通过 API 为你的博客网站创建一个 Share（只需做一次）：&lt;/p&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;# 登录获取 admin token
TOKEN&amp;#x3D;$(curl -s -X POST https:&amp;#x2F;&amp;#x2F;你的umami域名&amp;#x2F;api&amp;#x2F;auth&amp;#x2F;login \
  -H &amp;#39;Content-Type: application&amp;#x2F;json&amp;#39; \
  -d &amp;#39;&amp;#123;&amp;quot;username&amp;quot;:&amp;quot;admin&amp;quot;,&amp;quot;password&amp;quot;:&amp;quot;你的密码&amp;quot;&amp;#125;&amp;#39; | python3 -c &amp;#39;import sys,json;print(json.load(sys.stdin)[&amp;quot;token&amp;quot;])&amp;#39;)

# 为博客网站创建 share（websiteId 替换成你的）
SHARE_RESP&amp;#x3D;$(curl -s -X POST https:&amp;#x2F;&amp;#x2F;你的umami域名&amp;#x2F;api&amp;#x2F;websites&amp;#x2F;&amp;#123;websiteId&amp;#125;&amp;#x2F;shares \
  -H &amp;quot;Authorization: Bearer $TOKEN&amp;quot; \
  -H &amp;#39;Content-Type: application&amp;#x2F;json&amp;#39; \
  -d &amp;#39;&amp;#123;&amp;quot;name&amp;quot;:&amp;quot;blog-stats&amp;quot;,&amp;quot;parameters&amp;quot;:&amp;#123;&amp;quot;overview&amp;quot;:true,&amp;quot;events&amp;quot;:true&amp;#125;&amp;#125;&amp;#39;)

echo $SHARE_RESP&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;p&gt;记录返回的 &lt;code&gt;slug&lt;/code&gt; 值，然后通过 slug 获取 Share Token：&lt;/p&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;# 获取 Share JWT token（只读，仅限该网站）
curl https:&amp;#x2F;&amp;#x2F;你的umami域名&amp;#x2F;api&amp;#x2F;share&amp;#x2F;&amp;#123;slug&amp;#125;&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;p&gt;返回：&lt;/p&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-json&#34; data-language=&#34;json&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-json&#34;&gt;&amp;#123;
  &amp;quot;shareId&amp;quot;: &amp;quot;...&amp;quot;,
  &amp;quot;websiteId&amp;quot;: &amp;quot;...&amp;quot;,
  &amp;quot;token&amp;quot;: &amp;quot;eyJhbGciOiJIUzI1NiIs...&amp;quot;,
  &amp;quot;parameters&amp;quot;: &amp;#123; &amp;quot;overview&amp;quot;: true, &amp;quot;events&amp;quot;: true &amp;#125;
&amp;#125;&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;p&gt;&lt;code&gt;token&lt;/code&gt; 字段的值就是 Share Token，保存到前端配置中。&lt;/p&gt;
&lt;h3 id=&#34;2-API-差异说明&#34;&gt;2. API 差异说明&lt;/h3&gt;
&lt;p&gt;与 v2 相比，v3 有以下变化：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;项目&lt;/th&gt;
&lt;th&gt;v2&lt;/th&gt;
&lt;th&gt;v3&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;认证 Header&lt;/td&gt;
&lt;td&gt;&lt;code&gt;Authorization: Bearer &amp;lt;token&amp;gt;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;X-Umami-Share-Token: &amp;lt;token&amp;gt;&lt;/code&gt; + &lt;code&gt;X-Umami-Share-Context: share&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;响应格式&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123;&amp;quot;pageviews&amp;quot;:&amp;#123;&amp;quot;value&amp;quot;:N&amp;#125;&amp;#125;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123;&amp;quot;pageviews&amp;quot;: N&amp;#125;&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;页面过滤参数&lt;/td&gt;
&lt;td&gt;&lt;code&gt;?url=/path/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;?path=/path/&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;时间戳&lt;/td&gt;
&lt;td&gt;毫秒（不变）&lt;/td&gt;
&lt;td&gt;毫秒&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;h3 id=&#34;3-编写前端代码（v3）&#34;&gt;3. 编写前端代码（v3）&lt;/h3&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-markup&#34; data-language=&#34;markup&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-markup&#34;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html lang&amp;#x3D;&amp;quot;en&amp;quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;meta charset&amp;#x3D;&amp;quot;UTF-8&amp;quot;&amp;gt;
    &amp;lt;title&amp;gt;Umami 网站统计 - v3&amp;lt;&amp;#x2F;title&amp;gt;
&amp;lt;&amp;#x2F;head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;div style&amp;#x3D;&amp;quot;text-align:center;&amp;quot;&amp;gt;
        &amp;lt;h1&amp;gt;Umami 网站统计&amp;lt;&amp;#x2F;h1&amp;gt;
        &amp;lt;span&amp;gt;总访问量 &amp;lt;span id&amp;#x3D;&amp;quot;umami-site-pv&amp;quot;&amp;gt;&amp;lt;&amp;#x2F;span&amp;gt; 次&amp;lt;&amp;#x2F;span&amp;gt;
        &amp;lt;span&amp;gt;总访客数 &amp;lt;span id&amp;#x3D;&amp;quot;umami-site-uv&amp;quot;&amp;gt;&amp;lt;&amp;#x2F;span&amp;gt; 人&amp;lt;&amp;#x2F;span&amp;gt;
    &amp;lt;&amp;#x2F;div&amp;gt;

    &amp;lt;script&amp;gt;
        const website_id &amp;#x3D; &amp;#39;xxx&amp;#39;;       &amp;#x2F;&amp;#x2F; 你的网站 UUID
        const share_token &amp;#x3D; &amp;#39;xxx&amp;#39;;       &amp;#x2F;&amp;#x2F; 上一步获取的 Share JWT
        const api_server &amp;#x3D; &amp;#39;https:&amp;#x2F;&amp;#x2F;你的umami域名&amp;#39;;
        const start_time &amp;#x3D; new Date(&amp;#39;2024-01-01&amp;#39;).getTime();

        const request_url &amp;#x3D; api_server + &amp;#39;&amp;#x2F;api&amp;#x2F;websites&amp;#x2F;&amp;#39; + website_id + &amp;#39;&amp;#x2F;stats&amp;#39;;
        const params &amp;#x3D; new URLSearchParams(&amp;#123;
            startAt: start_time,
            endAt: new Date().getTime(),
        &amp;#125;);

        async function fetchStats() &amp;#123;
            const resp &amp;#x3D; await fetch(request_url + &amp;#39;?&amp;#39; + params, &amp;#123;
                headers: &amp;#123;
                    &amp;#39;X-Umami-Share-Token&amp;#39;: share_token,
                    &amp;#39;X-Umami-Share-Context&amp;#39;: &amp;#39;share&amp;#39;,
                &amp;#125;,
            &amp;#125;);
            const data &amp;#x3D; await resp.json();

            &amp;#x2F;&amp;#x2F; v3 直接返回数字，无需 .value
            document.querySelector(&amp;#39;#umami-site-pv&amp;#39;).textContent &amp;#x3D; data.pageviews;
            document.querySelector(&amp;#39;#umami-site-uv&amp;#39;).textContent &amp;#x3D; data.visitors;
        &amp;#125;
        fetchStats();
    &amp;lt;&amp;#x2F;script&amp;gt;
&amp;lt;&amp;#x2F;body&amp;gt;
&amp;lt;&amp;#x2F;html&amp;gt;&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;h3 id=&#34;4-获取单页浏览数&#34;&gt;4. 获取单页浏览数&lt;/h3&gt;
&lt;p&gt;v3 的过滤参数从 &lt;code&gt;url&lt;/code&gt; 改为了 &lt;code&gt;path&lt;/code&gt;：&lt;/p&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-javascript&#34; data-language=&#34;javascript&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-javascript&#34;&gt;&amp;#x2F;&amp;#x2F; v2: ?url&amp;#x3D;&amp;#x2F;posts&amp;#x2F;hello-world&amp;#x2F;
&amp;#x2F;&amp;#x2F; v3: ?path&amp;#x3D;&amp;#x2F;posts&amp;#x2F;hello-world&amp;#x2F;

async function pageStats(path) &amp;#123;
    const resp &amp;#x3D; await fetch(request_url + &amp;#39;?&amp;#39; + params + &amp;#39;&amp;amp;path&amp;#x3D;&amp;#39; + path, &amp;#123;
        headers: &amp;#123;
            &amp;#39;X-Umami-Share-Token&amp;#39;: share_token,
            &amp;#39;X-Umami-Share-Context&amp;#39;: &amp;#39;share&amp;#39;,
        &amp;#125;,
    &amp;#125;);
    const data &amp;#x3D; await resp.json();
    &amp;#x2F;&amp;#x2F; data.pageviews 就是该页面的浏览量
    console.log(path, &amp;#39;pageviews:&amp;#39;, data.pageviews);
&amp;#125;&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;h3 id=&#34;5-安全性说明&#34;&gt;5. 安全性说明&lt;/h3&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;方案&lt;/th&gt;
&lt;th&gt;泄露影响&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;v2: View only 用户 JWT&lt;/td&gt;
&lt;td&gt;可访问&lt;strong&gt;所有&lt;/strong&gt;网站 stats&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;v2: Admin 用户 JWT&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;完全控制权&lt;/strong&gt;（最危险）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;v3: Share Token&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;仅限单个网站&lt;/strong&gt; stats，只读&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;p&gt;Share Token 的 JWT payload 只包含：&lt;/p&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-json&#34; data-language=&#34;json&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-json&#34;&gt;&amp;#123; &amp;quot;shareId&amp;quot;: &amp;quot;...&amp;quot;, &amp;quot;websiteId&amp;quot;: &amp;quot;...&amp;quot;, &amp;quot;shareType&amp;quot;: 1 &amp;#125;&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;p&gt;没有用户身份，没有管理权限。即使完全公开在浏览器中，攻击者也&lt;strong&gt;只能看到这一个网站的访问统计数据&lt;/strong&gt;，而这些数据在页面上本来就已经公开显示。&lt;/p&gt;
&lt;h3 id=&#34;6-Token-过期处理&#34;&gt;6. Token 过期处理&lt;/h3&gt;
&lt;p&gt;Share Token 永不过期（除非你删除对应的 Share）。如果需要更换，只需：&lt;/p&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;# 列出所有 shares
curl https:&amp;#x2F;&amp;#x2F;你的umami域名&amp;#x2F;api&amp;#x2F;websites&amp;#x2F;&amp;#123;websiteId&amp;#125;&amp;#x2F;shares \
  -H &amp;quot;Authorization: Bearer $TOKEN&amp;quot;

# 删除旧的
curl -X DELETE https:&amp;#x2F;&amp;#x2F;你的umami域名&amp;#x2F;api&amp;#x2F;share&amp;#x2F;id&amp;#x2F;&amp;#123;shareId&amp;#125; \
  -H &amp;quot;Authorization: Bearer $TOKEN&amp;quot;

# 重新创建
curl -X POST https:&amp;#x2F;&amp;#x2F;你的umami域名&amp;#x2F;api&amp;#x2F;websites&amp;#x2F;&amp;#123;websiteId&amp;#125;&amp;#x2F;shares \
  -H &amp;quot;Authorization: Bearer $TOKEN&amp;quot; \
  -H &amp;#39;Content-Type: application&amp;#x2F;json&amp;#39; \
  -d &amp;#39;&amp;#123;&amp;quot;name&amp;quot;:&amp;quot;blog-stats&amp;quot;,&amp;quot;parameters&amp;quot;:&amp;#123;&amp;quot;overview&amp;quot;:true,&amp;quot;events&amp;quot;:true&amp;#125;&amp;#125;&amp;#39;&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;hr&gt;
