	&amp;lt;img src&amp;#x3D;&amp;quot;https:&amp;#x2F;&amp;#x2F;npm.elemecdn.com&amp;#x2F;hexo-butterfly-envelope&amp;#x2F;lib&amp;#x2F;violet.jpg&amp;quot; style&amp;#x3D;&amp;quot;width:100%;overflow:hidden;pointer-events:none&amp;quot;&amp;gt;
