        &amp;#123; &amp;quot;key&amp;quot;: &amp;quot;Access-Control-Allow-Origin&amp;quot;, &amp;quot;value&amp;quot;: &amp;quot;*&amp;quot; &amp;#125;
      ]
    &amp;#125;,
    &amp;#123;
      &amp;quot;source&amp;quot;: &amp;quot;&amp;#x2F;(.*)\\.mjs&amp;quot;,
