&lt;h3 id=&#34;iframe-页面镶套&#34;&gt;iframe 页面镶套&lt;/h3&gt;
&lt;p&gt;iframe 页面镶套可以帮助我们更好的展示一个页面。比如以下演示页面。&lt;/p&gt;
&lt;h4 id=&#34;iframe自动加载&#34;&gt;iframe自动加载&lt;/h4&gt;
&lt;iframe src=&#34;/galleries/&#34; width=&#34;100%&#34; height=&#34;500&#34; loading=&#34;lazy&#34; name=&#34;topFrame&#34; scrolling=&#34;yes&#34;  noresize=&#34;noresize&#34; frameborder=&#34;0&#34; id=&#34;topFrame&#34; loading=&#34;lazy&#34;&gt;&lt;/iframe&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-markup&#34; data-language=&#34;markup&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-markup&#34;&gt;&amp;lt;iframe src&amp;#x3D;&amp;quot;&amp;#x2F;galleries&amp;#x2F;&amp;quot; width&amp;#x3D;&amp;quot;100%&amp;quot; height&amp;#x3D;&amp;quot;500&amp;quot; loading&amp;#x3D;&amp;quot;lazy&amp;quot; name&amp;#x3D;&amp;quot;topFrame&amp;quot; scrolling&amp;#x3D;&amp;quot;yes&amp;quot;  noresize&amp;#x3D;&amp;quot;noresize&amp;quot; frameborder&amp;#x3D;&amp;quot;0&amp;quot; id&amp;#x3D;&amp;quot;topFrame&amp;quot; loading&amp;#x3D;&amp;quot;lazy&amp;quot;&amp;gt;&amp;lt;&amp;#x2F;iframe&amp;gt;&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;h4 id=&#34;iframe鼠标点击加载&#34;&gt;iframe鼠标点击加载&lt;/h4&gt;
  &lt;ul&gt;
    &lt;li&gt; &lt;a id=&#34;download&#34; onclick=&#34;frameA.src=&#39;/&#39;&#34;  aria-label=&#34;iframe测试&#34;&gt;点击加载主页&lt;/a&gt; &lt;/li&gt;
    &lt;li&gt; &lt;a id=&#34;download&#34; onclick=&#34;frameB.location=&#39;/galleries/&#39;&#34; &gt;点击加载相册&lt;/a&gt; &lt;/li&gt;
  &lt;/ul&gt;
  &lt;iframe id=&#34;frameA&#34; src=&#34;&#34; loading=&#34;lazy&#34; style=&#34;width:100%;height:500px;background-image:url(/medias_webp/loading.webp);background-size: 100% 100%;&#34; frameborder=&#34;0&#34;&gt;&lt;/iframe&gt;  
&lt;iframe name=&#34;frameB&#34; src=&#34;&#34; loading=&#34;lazy&#34; style=&#34;width:100%;height:500px;background-image:url(/medias_webp/loading.webp);background-size: 100% 100%;&#34;  frameborder=&#34;2&#34;&gt;&lt;/iframe&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-markup&#34; data-language=&#34;markup&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-markup&#34;&gt;  &amp;lt;ul&amp;gt;
    &amp;lt;li&amp;gt; &amp;lt;a id&amp;#x3D;&amp;quot;download&amp;quot; onclick&amp;#x3D;&amp;quot;frameA.src&amp;#x3D;&amp;#39;&amp;#x2F;&amp;#39;&amp;quot;  aria-label&amp;#x3D;&amp;quot;iframe测试&amp;quot;&amp;gt;点击加载主页&amp;lt;&amp;#x2F;a&amp;gt; &amp;lt;&amp;#x2F;li&amp;gt;
    &amp;lt;li&amp;gt; &amp;lt;a id&amp;#x3D;&amp;quot;download&amp;quot; onclick&amp;#x3D;&amp;quot;frameB.location&amp;#x3D;&amp;#39;&amp;#x2F;galleries&amp;#x2F;&amp;#39;&amp;quot; &amp;gt;点击加载相册&amp;lt;&amp;#x2F;a&amp;gt; &amp;lt;&amp;#x2F;li&amp;gt;
  &amp;lt;&amp;#x2F;ul&amp;gt;
  &amp;lt;iframe id&amp;#x3D;&amp;quot;frameA&amp;quot; src&amp;#x3D;&amp;quot;&amp;quot; loading&amp;#x3D;&amp;quot;lazy&amp;quot; style&amp;#x3D;&amp;quot;width:100%;height:500px;background-image:url(&amp;#x2F;medias_webp&amp;#x2F;loading.webp);background-size: 100% 100%;&amp;quot; frameborder&amp;#x3D;&amp;quot;0&amp;quot;&amp;gt;&amp;lt;&amp;#x2F;iframe&amp;gt;  
&amp;lt;iframe name&amp;#x3D;&amp;quot;frameB&amp;quot; src&amp;#x3D;&amp;quot;&amp;quot; loading&amp;#x3D;&amp;quot;lazy&amp;quot; style&amp;#x3D;&amp;quot;width:100%;height:500px;background-image:url(&amp;#x2F;medias_webp&amp;#x2F;loading.webp);background-size: 100% 100%;&amp;quot;  frameborder&amp;#x3D;&amp;quot;2&amp;quot;&amp;gt;&amp;lt;&amp;#x2F;iframe&amp;gt;&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;h3 id=&#34;object标签&#34;&gt;object标签&lt;/h3&gt;
&lt;p&gt;&lt;object width=&#34;100%&#34; height=&#34;400&#34; data=&#34;/galleries/&#34;&gt;&lt;/object&gt;&lt;/p&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-markup&#34; data-language=&#34;markup&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-markup&#34;&gt;&amp;lt;object width&amp;#x3D;&amp;quot;100%&amp;quot; height&amp;#x3D;&amp;quot;400&amp;quot; data&amp;#x3D;&amp;quot;&amp;#x2F;galleries&amp;#x2F;&amp;quot;&amp;gt;&amp;lt;&amp;#x2F;object&amp;gt;&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
&lt;h3 id=&#34;details-标签&#34;&gt;details 标签&lt;/h3&gt;
&lt;p&gt;用于展示代码较多需要折叠或折叠相关内容，以下为演示。&lt;code&gt;summary&lt;/code&gt; 填写显示名称。&lt;/p&gt;
